 const rate=/(?:average pay (?:over )?|up to |approximately |top experts earn |over )?[$£€][\d,]+[Kk]?(?:[–-]\s*[$£€]?[\d,]+[Kk]?)?\+?(?:\/(?:hour|week|month)|\s+(?:per approved hour|per hour(?: equivalent)?|hourly rates|salary|base))/gi;
