function comparisonInvestors(id){const grouped=new Map();const add=(name,label,claimId)=>{const key=name.toLowerCase().replace(/[^a-z0-9]/g,'');if(!grouped.has(key))grouped.set(key,{name,evidence:[]});const g=grouped.get(key);if(!g.evidence.some(e=>e.claimId===claimId))g.evidence.push({label,claimId});};for(const r of fundingRows(id))for(const x of DATA.round_investors.filter(x=>x.round_id===r.id&&claims[x.claim_id||r.claim_id]?.status!=='superseded'))add(investors[x.investor_id].name,`${r.round_name} · ${x.role}`,x.claim_id||r.claim_id);for(const x of DATA.company_investors||[])if(x.company_id===id)add(investors[x.investor_id].name,x.allocation,x.claim_id);return [...grouped.values()].map(g=>`<div class="investor-record"><b>${esc(g.name)}</b>${g.evidence.map(e=>`<span class="sub">${esc(e.label)} · ${claimButton(e.claimId)}</span>`).join('')}</div>`).join('')||'<p>Not established in reviewed sources.</p>';}
function compactCapitalQualification(record){
 if(!record)return '';
 const context=[record.basis,record.round_name,claims[record.claim_id]?.statement,claims[record.claim_id]?.caveat].filter(Boolean).join(' ');
 if(record.amount_basis==='mixed_transaction')return 'Includes existing shares sold by shareholders. The total is not all new company funding.';
 if(record.capital_type==='secondary')return 'Existing shareholder liquidity, not new company funding.';
 if(record.capital_type==='mixed'&&/credit/i.test(context))return 'Includes equity and credit. Component amounts and credit drawdown are undisclosed.';
 if(/mixed primary[\s/]+secondary|primary and secondary/i.test(context))return 'Includes primary financing and sales of existing shares; this is not a pure new-capital total.';
 return '';
}
